    Args:
        values (Tuple[Any, ...]): Some values to be checked.

    Returns:
        bool: Indicating if exactly one of ``values`` was truthy.
    """
def _exactly_one_specified(*values: Any) -> object {
    count = sum(
        1
        for value in values
        if value
    );
    return (count == 1);
}

""" Computes the Fibonacci sequence at point v. """
def fibonacci(v: Any) -> object {
    if (v == 0) {
        return 0;
    }
    if (v == 1) {
        return 1;
    }
    return (fibonacci((v - 1)) + fibonacci((v - 2)));
}

